ALTER TABLE public.ads ADD COLUMN IF NOT EXISTS legacy_source text, ADD COLUMN IF NOT EXISTS legacy_id uuid;
CREATE UNIQUE INDEX IF NOT EXISTS ads_legacy_source_id_idx ON public.ads(legacy_source,legacy_id);
ALTER TABLE public.decisions ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS legacy_source text, ADD COLUMN IF NOT EXISTS legacy_id uuid;
CREATE UNIQUE INDEX IF NOT EXISTS decisions_legacy_source_id_idx ON public.decisions(legacy_source,legacy_id);
