INSERT INTO public.ads(user_id,template_id,name,canvas_data,legacy_source,legacy_id) SELECT user_id,template_id,'Recovered canvas draft',canvas_data,'user_canvas_drafts',id FROM public.user_canvas_drafts WHERE canvas_data IS NOT NULL ON CONFLICT(legacy_source,legacy_id) DO NOTHING;
INSERT INTO public.ads(user_id,template_id,name,content,status,legacy_source,legacy_id) SELECT user_id,template_id,name,content,status,'user_ads',id FROM public.user_ads ON CONFLICT(legacy_source,legacy_id) DO NOTHING;
INSERT INTO public.ads(user_id,name,content,legacy_source,legacy_id) SELECT user_id,product_name,jsonb_build_object('generatedContent',content,'adType',ad_type,'platform',platform,'generationPrompt',generation_prompt),'generated_ads',id FROM public.generated_ads ON CONFLICT(legacy_source,legacy_id) DO NOTHING;
INSERT INTO public.decisions(user_id,campaign_id,page,trigger_source,category,signal,action,reasoning,confidence,status,created_at,metadata,legacy_source,legacy_id) SELECT user_id,campaign_id,'/analytics','analytics',category,description,title,reasoning,confidence,status,created_at,jsonb_build_object('title',title,'description',description,'supporting_data',supporting_data,'suggested_action',suggested_action,'priority',priority),'ai_recommendations',id FROM public.ai_recommendations ON CONFLICT(legacy_source,legacy_id) DO NOTHING;
INSERT INTO public.decisions(user_id,page,trigger_source,signal,action,metadata,created_at,legacy_source,legacy_id) SELECT user_id,'/visual-editor','legacy_suggestion',suggestion_type,suggestion_type,jsonb_build_object('suggestions',suggestions,'template_id',template_id),created_at,'ai_suggestions',id FROM public.ai_suggestions ON CONFLICT(legacy_source,legacy_id) DO NOTHING;